 "Créer la map dans {0}": "Create the map in {0}",
 "Ignorer": "Ignore",
 "Accueil de Forge : « Relier » sur chaque map, ou « Créer les maps et relier » pour vos projets UEFN.": "Forge home: “Link” on each map, or “Create the maps and link” for your UEFN projects.",
 "Ces écrans se débloquent tout seuls dès que l’abonnement est actif.": "These screens unlock on their own as soon as the plan is active.",
 "Créer les maps et relier ({0}) dans {1}": "Create the maps and link ({0}) in {1}",
 "Créez le projet dans UEFN, puis dans POP Forge : Accueil → cette map → « Relier ».": "Create the project in UEFN, then in POP Forge: Home → this map → “Link”.",
 "Dans Forge, Accueil : « Relier » sur chaque map, ou « Créer les maps et relier » pour les projets UEFN qui n’ont pas encore de map. Laissez Forge ouvert.": "In Forge, Home: “Link” on each map, or “Create the maps and link” for UEFN projects that don’t have a map yet. Keep Forge open.",
 "Dans Forge, Accueil → « Créer les maps et relier » : une map par projet UEFN, synchronisée. Laissez Forge ouvert.": "In Forge, Home → “Create the maps and link”: one map per UEFN project, kept in sync. Keep Forge open.",
 "En attente de Forge… cette page s’ouvrira toute seule dès que vos projets seront importés.": "Waiting for Forge… this page will open on its own as soon as your projects are imported.",
 "Gratuit comme relais UEFN. Ouvrez cette page sur le PC pour le télécharger directement dessus.": "Free as a UEFN relay. Open this page on the PC to download it there directly.",
 "Inclus dans l’abonnement Pro": "Included in the Pro plan",
 "Installez POP Forge sur le PC où UEFN tourne (gratuit comme relais, Paramètres → UEFN Link). Dans UEFN : Enable Project Python Scripts, puis Model Context Protocol → Start Server.": "Install POP Forge on the PC where UEFN runs (free as a relay, Settings → UEFN Link). In UEFN: Enable Project Python Scripts, then Model Context Protocol → Start Server.",
 "Installez et ouvrez POP Forge, puis connectez-vous.": "Install and open POP Forge, then log in.",
 "Laissez Forge ouvert : le badge en haut passe à « Relais en ligne ».": "Keep Forge open: the badge at the top switches to “Relay online”.",
 "Le relais est hors ligne quand POP Forge n’est pas lancé, ou que UEFN ou son serveur MCP n’est pas démarré.": "The relay is offline when POP Forge isn’t running, or when UEFN or its MCP server isn’t started.",
 "Les agents, les vérifications, la bibliothèque et les outils de Forge construisent votre map dans UEFN avec vos IA. Ils sont inclus dans l’abonnement Pro, essai gratuit compris. Sans Pro, Forge reste votre relais UEFN : il relie vos projets et pilote UEFN pour le site et vos IA connectées.": "Forge’s agents, checks, library and tools build your map in UEFN with your AIs. They are included in the Pro plan, free trial included. Without Pro, Forge stays your UEFN relay: it links your projects and drives UEFN for the website and your connected AIs.",
 "L’application Windows de POP : elle relie vos projets UEFN à POP (gratuit), et avec Pro vos IA y construisent la map pendant que vous suivez tout au même endroit.": "POP’s Windows app: it links your UEFN projects to POP (free), and with Pro your AIs build the map there while you follow everything in one place.",
 "Oui pour tout POP, dans le navigateur. Seul POP Forge doit tourner sur le PC Windows où UEFN est ouvert (UEFN n’existe pas sur Mac).": "Yes for all of POP, in the browser. Only POP Forge has to run on the Windows PC where UEFN is open (UEFN doesn’t exist on Mac).",
 "Ouvrez Forge et connectez-vous avec votre compte POP.": "Open Forge and log in with your POP account.",
 "POP Forge est l’application Windows à lancer sur le PC où UEFN est ouvert (gratuite comme relais). Elle relie vos projets et les garde synchronisés.": "POP Forge is the Windows app to run on the PC where UEFN is open (free as a relay). It links your projects and keeps them in sync.",
 "POP Forge remplace UEFN Link (pop-link.exe) : fermez l’ancien relais avant de lancer Forge, vos projets déjà reliés sont repris.": "POP Forge replaces UEFN Link (pop-link.exe): close the old relay before starting Forge; your already linked projects are kept.",
 "POP Forge tourne sur le PC Windows où UEFN est ouvert. Il ne touche qu’aux projets reliés et pilote UEFN par son serveur MCP officiel. Gratuit comme relais.": "POP Forge runs on the Windows PC where UEFN is open. It only touches linked projects and drives UEFN through its official MCP server. Free as a relay.",
 "Projets UEFN trouvés sur ce PC sans map POP.": "UEFN projects found on this PC without a POP map.",
 "Relais UEFN : dans POP Forge, Réglages → Diagnostic, puis collez le résultat dans votre demande. Mot de passe perdu : « Mot de passe oublié » sur la page de connexion, ou demandez un lien à un admin du studio.": "UEFN relay: in POP Forge, Settings → Diagnostics, then paste the result into your request. Lost password: “Forgot password” on the login page, or ask a studio admin for a link.",
 "Relais périmé : il est plus ancien que POP et ne connaît pas toutes les actions (session de test, poser un appareil, importer un fichier…). Installez la dernière version de POP Forge, fermez l’ancien relais et lancez Forge.": "Outdated relay: it is older than POP and doesn’t know every action (test session, placing a device, importing a file…). Install the latest POP Forge, close the old relay and start Forge.",
 "Relais périmé : installez la dernière version de POP Forge (ci-dessous).": "Outdated relay: install the latest POP Forge (below).",
 "Relier UEFN avec POP Forge": "Link UEFN with POP Forge",
 "Toujours rien ? Dans Forge : Réglages → Diagnostic, et gardez le résultat.": "Still nothing? In Forge: Settings → Diagnostics, and keep the result.",
 "Télécharger POP Forge (Windows)": "Download POP Forge (Windows)",
 "Téléchargez POP Forge (Paramètres → UEFN, ou pop-uefn.com/forge) et installez-le sur le PC.": "Download POP Forge (Settings → UEFN, or pop-uefn.com/forge) and install it on the PC.",
 "UEFN Link (pop-link.exe) est remplacé par POP Forge, gratuit comme relais. Installez Forge, fermez pop-link.exe puis lancez Forge : vos projets déjà reliés sont repris.": "UEFN Link (pop-link.exe) is replaced by POP Forge, free as a relay. Install Forge, close pop-link.exe, then start Forge: your already linked projects are kept.",
 "Un compte POP : Forge est gratuit comme relais UEFN ; ses agents, vérifications, bibliothèque et outils sont inclus dans l’abonnement Pro (essai gratuit compris).": "A POP account: Forge is free as a UEFN relay; its agents, checks, library and tools are included in the Pro plan (free trial included).",
