 "Seul ou en équipe": "Solo or team",
 "Mes maps": "My maps",
 "Vous travaillez seul sur « {0} »": "You’re working solo on “{0}”",
 "Cette map est dans vos maps perso : personne d’autre n’y a accès.": "This map is in your personal maps: nobody else has access.",
 "Tout marche pareil en solo : tâches, planning, pages, tableau blanc, Organiseur, IA connectées et analyse. Popy vous propose quoi faire chaque jour.": "Everything works the same solo: tasks, planning, pages, whiteboard, Organizer, connected AIs and analytics. Popy suggests what to do each day.",
 "Travailler en équipe sur cette map": "Work on this map as a team",
 "La map passe dans un studio avec tout son contenu (tâches, pages, tableaux, gains). Vous pourrez ensuite inviter des membres.": "The map moves into a studio with all its content (tasks, pages, boards, earnings). You can then invite members.",
