 "Passer en équipe": "Switch to team",
 "Vos maps perso sont pour travailler seul. Pour inviter quelqu’un, passez la map dans un studio (Équipe → Travailler en équipe).": "Your personal maps are for working solo. To invite someone, move the map into a studio (Team → Work as a team).",
 "Votre espace perso ne se renomme pas, ne se supprime pas et ne se transfère pas.": "Your personal space can’t be renamed, deleted or transferred.",
 "C’est la dernière map du studio : elle ne peut pas le quitter.": "This is the studio’s last map: it can’t leave it.",
 "Choisissez un studio.": "Choose a studio.",
 "Map passée dans un studio": "Map moved into a studio",
 "Cliquez sur le sélecteur « Map » en haut à gauche : vous y changez de map, et vous trouvez « Nouvelle map dans ce studio » et « Nouveau studio ». C’est aussi dans le menu du compte (en haut à droite).": "Click the “Map” selector at the top left: that’s where you switch maps, and where you’ll find “New map in this studio” and “New studio”. It’s also in the account menu (top right).",
 "Ctrl+K (Cmd+K) ouvre la recherche : tâches, pages, tableaux, acteurs, membres et actions. Majuscules et accents ne comptent pas.": "Ctrl+K (Cmd+K) opens search: tasks, pages, boards, actors, members and actions. Capital letters and accents don’t matter.",
 "POP est l’espace de travail des créateurs UEFN : tâches d’une heure et planning, pages et tableau blanc, UEFN Link, IA connectées qui connaissent la map, analyse du marché, playtests et partage des gains. Popy, l’assistant intégré, vous guide au quotidien.": "POP is the workspace for UEFN creators: one-hour tasks and planning, pages and whiteboard, an Organizer linked to UEFN, connected AIs, market analysis, playtests and revenue sharing. Popy, the built-in assistant, guides you day to day.",
 "Ctrl+K recherche · Ctrl+Z annuler (tableau) · Ctrl+B/I/U gras, italique, souligné sur le tableau · Ctrl+0 tout voir · Échap fermer.": "Ctrl+K search · Ctrl+Z undo (board, Organizer) · Ctrl+B/I/U bold, italic, underline on the board · Ctrl+0 fit all · Esc close.",
 "UEFN Link et IA connectées": "UEFN: Organizer and connected AIs",
