 "Relais périmé : votre UEFN Link ne connaît pas cette action. Téléchargez la nouvelle version depuis l’Organiseur (UEFN Link → Télécharger UEFN Link), puis relancez-le.": "Outdated relay: your UEFN Link doesn’t know this action. Download the new version from the Organizer (UEFN Link → Download UEFN Link), then restart it.",
 "Relais périmé : votre UEFN Link est plus ancien que POP et ne connaît pas toutes les actions (session de test, poser un appareil, importer un fichier…). Téléchargez la nouvelle version, fermez l’ancienne fenêtre et lancez la nouvelle.": "Outdated relay: your UEFN Link is older than POP and doesn’t know every action (test session, placing a device, importing a file…). Download the new version, close the old window and start the new one.",
