 "Prendre": "Take",
 "Popy lit vos tâches, vos objectifs et votre équipe, et répond aussi aux questions sur POP. Tout reste dans POP.": "Popy reads your tasks, goals and team, and also answers questions about POP. Everything stays in POP.",
 "Posez-moi une question : sur votre map (« qu’est-ce qui est en retard ? », « sur quoi travaille Hugo ? », « où en est la tâche #12 ? ») ou sur POP (« comment relier UEFN ? »).": "Ask me a question: about your map (“what’s late?”, “what is Hugo working on?”, “where is task #12 at?”) or about POP (“how do I link UEFN?”).",
 "Je n’ai pas de fiche sur ce sujet, mais voici ce que j’ai trouvé dans votre map :": "I don’t have an article on this, but here’s what I found in your map:",
 "Je n’ai pas trouvé de réponse. Reformulez avec d’autres mots, ou choisissez un sujet ci-dessous.": "I couldn’t find an answer. Try other words, or pick a topic below.",
