 "Dashboard": "Dashboard",
  "Dans Claude, cliquez « Ajouter un connecteur personnalisé » et collez l’adresse.": "In Claude, click “Add custom connector” and paste the address.",
  "Le bouton ouvre la page des connecteurs de Claude. Sinon : Paramètres → Connecteurs. Offre gratuite : un seul connecteur personnalisé.": "The button opens Claude’s connectors page. Otherwise: Settings → Connectors. Free plan: one custom connector.",
  "Dans ChatGPT, cliquez + puis « Add custom MCP server » et collez l’adresse.": "In ChatGPT, click + then “Add custom MCP server” and paste the address.",
  "Sur ordinateur (chatgpt.com). Selon OpenAI : écriture avec Business, Enterprise et Edu, lecture seule avec Pro.": "On a computer (chatgpt.com). According to OpenAI: write access on Business, Enterprise and Edu, read-only on Pro.",
  "Dans Gemini, Paramètres → Connected Apps → « Add a custom app », collez l’adresse.": "In Gemini, Settings → Connected Apps → “Add a custom app”, paste the address.",
  "Selon Google, pour l’instant : 18 ans ou plus, aux États-Unis, compte personnel, Gemini en anglais.": "According to Google, for now: 18 or older, in the US, personal account, Gemini in English.",
  "Dans Le Chat, Connecteurs → « + Add Connector » → « Custom MCP Connector », collez l’adresse.": "In Le Chat, Connectors → “+ Add Connector” → “Custom MCP Connector”, paste the address.",
  "Réservé à l’administrateur de l’espace (vous, sur les offres Free, Pro et Student).": "For the workspace admin only (you, on Free, Pro and Student plans).",
  "Dans VS Code, démarrez le serveur pop (mode Agent de Copilot).": "In VS Code, start the pop server (Copilot Agent mode).",
  "Dans Windsurf : Cascade → MCP → « View raw config », collez, puis « Refresh ».": "In Windsurf: Cascade → MCP → “View raw config”, paste, then “Refresh”.",
  "Collez la commande dans un terminal (sinon ensuite : codex mcp login pop).": "Paste the command into a terminal (if needed afterwards: codex mcp login pop).",
  "Collez la commande dans un terminal, puis tapez /mcp dans Claude Code et choisissez pop.": "Paste the command into a terminal, then type /mcp in Claude Code and pick pop.",
  "Collez la commande dans un terminal, puis tapez /mcp auth pop dans Gemini.": "Paste the command into a terminal, then type /mcp auth pop in Gemini.",
  "Dans votre IA, ajoutez un serveur MCP « HTTP » avec cette adresse.": "In your AI, add an “HTTP” MCP server with this address.",
  "Anciens clients : transport SSE à l’adresse /sse.": "Older clients: SSE transport at /sse.",
