  "Révoquer {0}": "Revoke {0}",
  "Révoquer {0} ? Son accès à POP est coupé tout de suite ; pour la reconnecter, refaites la connexion.": "Revoke {0}? Its access to POP is cut off immediately; to reconnect it, connect it again.",
  "Sur claude.ai ou dans l’application Claude : Personnaliser → Connecteurs.": "On claude.ai or in the Claude app: Customize → Connectors.",
  "Cliquez « Ajouter un connecteur personnalisé », collez l’adresse de POP, puis « Ajouter ».": "Click “Add custom connector”, paste POP’s address, then “Add”.",
  "Cliquez « Connecter » : la page POP s’ouvre, cliquez « Autoriser ».": "Click “Connect”: the POP page opens, click “Allow”.",
  "Ouvrir Claude": "Open Claude",
  "Offre gratuite : un seul connecteur personnalisé. Équipe et Entreprise : un propriétaire ajoute d’abord POP dans Paramètres de l’organisation → Connecteurs.": "Free plan: one custom connector. Team and Enterprise: an Owner first adds POP in Organization settings → Connectors.",
  "Adresse à coller à la place (la clé est dedans) :": "Address to paste instead (the key is included):",
  "Sur chatgpt.com (ordinateur), ouvrez Plugins (chatgpt.com/plugins).": "On chatgpt.com (computer), open Plugins (chatgpt.com/plugins).",
  "Bouton + → « Add custom MCP server » : nom POP, collez l’adresse de POP sous « Connection », authentification OAuth.": "+ button → “Add custom MCP server”: name POP, paste POP’s address under “Connection”, OAuth authentication.",
  "Cochez l’avertissement, « Create as a plugin », installez-le, puis cliquez « Autoriser » dans la page POP.": "Tick the warning, “Create as a plugin”, install it, then click “Allow” on the POP page.",
  "Dans une conversation, tapez @ et choisissez POP.": "In a conversation, type @ and pick POP.",
  "Ouvrir ChatGPT": "Open ChatGPT",
  "Selon OpenAI : sur le web seulement ; outils en écriture avec les offres Business, Enterprise et Edu, lecture seule avec Pro.": "According to OpenAI: web only; write tools on Business, Enterprise and Edu plans, read-only on Pro.",
  "Sur gemini.google.com (ordinateur) : Paramètres → Connected Apps (ou Personal Intelligence → Connected Apps).": "On gemini.google.com (computer): Settings → Connected Apps (or Personal Intelligence → Connected Apps).",
  "Sous « Custom apps », cliquez « Add a custom app » et collez l’adresse de POP, puis « Next ».": "Under “Custom apps”, click “Add a custom app”, paste POP’s address, then “Next”.",
  "Suivez les instructions : la page POP s’ouvre, cliquez « Autoriser ».": "Follow the instructions: the POP page opens, click “Allow”.",
  "Ouvrir Gemini": "Open Gemini",
  "Selon Google, pour l’instant : 18 ans ou plus, aux États-Unis, compte Google personnel, Gemini en anglais, historique activé. Ensuite, POP marche aussi dans l’application mobile.": "According to Google, for now: 18 or older, in the US, personal Google Account, Gemini in English, history turned on. POP then also works in the mobile app.",
  "Dans Le Chat (Mistral) : panneau de gauche → Intelligence → Connecteurs.": "In Le Chat (Mistral): left panel → Intelligence → Connectors.",
  "« + Add Connector », onglet « Custom MCP Connector » : nom pop, serveur : collez l’adresse de POP, authentification OAuth.": "“+ Add Connector”, “Custom MCP Connector” tab: name pop, server: paste POP’s address, OAuth authentication.",
  "Cliquez « Connect » : la page POP s’ouvre, cliquez « Autoriser ».": "Click “Connect”: the POP page opens, click “Allow”.",
  "Ouvrir Le Chat": "Open Le Chat",
  "Réservé aux administrateurs de l’espace (par défaut sur les offres Free, Pro et Student).": "Workspace admins only (the default on Free, Pro and Student plans).",
  "Ou choisissez l’authentification « HTTP Bearer Token » et collez cette clé :": "Or choose “HTTP Bearer Token” authentication and paste this key:",
  "Cliquez « Installer dans Cursor » et acceptez, ou ajoutez la configuration dans ~/.cursor/mcp.json.": "Click “Install in Cursor” and accept, or add the configuration to ~/.cursor/mcp.json.",
  "Dans Cursor, Réglages → MCP : cliquez « Connect » à côté de pop.": "In Cursor, Settings → MCP: click “Connect” next to pop.",
  "La page POP s’ouvre : cliquez « Autoriser ».": "The POP page opens: click “Allow”.",
  "Cliquez « Installer dans VS Code », ou ajoutez la configuration dans .vscode/mcp.json (commande « MCP: Add Server »).": "Click “Install in VS Code”, or add the configuration to .vscode/mcp.json (“MCP: Add Server” command).",
  "Démarrez le serveur pop : VS Code ouvre la connexion dans le navigateur.": "Start the pop server: VS Code opens sign-in in the browser.",
  "La page POP s’ouvre : cliquez « Autoriser ». Les outils sont dans le mode Agent de Copilot.": "The POP page opens: click “Allow”. The tools are in Copilot’s Agent mode.",
  "Dans Cascade, menu MCP → « View raw config » (fichier ~/.codeium/windsurf/mcp_config.json) et collez la configuration.": "In Cascade, MCP menu → “View raw config” (file ~/.codeium/windsurf/mcp_config.json) and paste the configuration.",
  "Enregistrez et cliquez « Refresh » : Windsurf ouvre la page POP.": "Save and click “Refresh”: Windsurf opens the POP page.",
  "Cliquez « Autoriser ».": "Click “Allow”.",
  "Dans un terminal, lancez la commande (elle ajoute pop à ~/.codex/config.toml, partagé par la CLI et l’extension).": "In a terminal, run the command (it adds pop to ~/.codex/config.toml, shared by the CLI and the extension).",
  "Puis lancez : codex mcp login pop": "Then run: codex mcp login pop",
  "Dans ~/.codex/config.toml :": "In ~/.codex/config.toml:",
  "Dans un terminal, lancez la commande.": "In a terminal, run the command.",
  "Lancez Claude Code et tapez /mcp, choisissez pop puis « Authenticate » (ou : claude mcp login pop).": "Start Claude Code, type /mcp, pick pop then “Authenticate” (or: claude mcp login pop).",
  "Dans un terminal :": "In a terminal:",
  "Lancez gemini et tapez /mcp auth pop.": "Start gemini and type /mcp auth pop.",
  "Autre client MCP": "Other MCP client",
  "Ajoutez un serveur MCP distant « Streamable HTTP » (parfois « HTTP ») avec l’adresse de POP.": "Add a remote “Streamable HTTP” (sometimes “HTTP”) MCP server with POP’s address.",
  "Si votre IA gère la connexion OAuth de MCP, elle ouvre POP : cliquez « Autoriser ».": "If your AI supports MCP’s OAuth sign-in, it opens POP: click “Allow”.",
  "Sinon, créez une clé : en-tête Authorization: Bearer, ou adresse avec ?token=. Anciens clients : transport SSE à l’adresse /sse.": "Otherwise, create a key: Authorization: Bearer header, or the address with ?token=. Older clients: SSE transport at /sse.",
  "Adresse : {0}\nEn-tête : Authorization: Bearer {1}\nOu adresse avec la clé : {0}?token={1}\nAncien transport SSE : {2}?token={1}": "Address: {0}\nHeader: Authorization: Bearer {1}\nOr address with the key: {0}?token={1}\nOlder SSE transport: {2}?token={1}",
