  ", créez une application et ajoutez du crédit : la lecture des messages est payante chez X (environ 0,005 $ par message lu, 150 messages au plus par collecte).": ", create an app and add credit: reading posts is paid on X (about $0.005 per post read, at most 150 posts per collection).",
  "Clé": "Key",
  "Concurrence moyenne": "Medium competition",
  "Connectez une ou plusieurs sources pour voir aussi ce dont on parle en ce moment. Sinon, passez : POP analyse les joueurs, Discover et les nouvelles maps. Vous pourrez connecter une source à tout moment.": "Connect one or more sources to also see what people are talking about right now. Or skip: POP analyses players, Discover and new maps. You can connect a source at any time.",
