  "Connecter une IA en un clic": "Connect an AI in one click",
  "Choisissez votre IA : elle ouvre POP, vous cliquez sur « Autoriser », c’est connecté. Aucune clé à copier.": "Pick your AI: it opens POP, you click “Authorize”, and you’re connected. No key to copy.",
  "Dans IA connectées, choisissez votre IA sous « Connecter une IA en un clic » : ajoutez l’adresse de POP dans l’IA (ou installez-la en un clic pour Cursor et VS Code), puis cliquez « Autoriser » dans la page POP qui s’ouvre. Aucune clé à copier. Pour une IA qui ne propose pas de se connecter, créez une clé API.": "In Connected AIs, pick your AI under “Connect an AI in one click”: add POP’s address in the AI (or install in one click for Cursor and VS Code), then click “Authorize” on the POP page that opens. No key to copy. For an AI that doesn’t offer sign-in, create an API key.",
  "Ouvrez Paramètres → IA connectées.": "Open Settings → Connected AIs.",
  "Choisissez votre IA (Claude, ChatGPT, Cursor, VS Code, Claude Code…) et suivez les 3 étapes.": "Pick your AI (Claude, ChatGPT, Cursor, VS Code, Claude Code…) and follow the 3 steps.",
  "Dans la page POP qui s’ouvre, choisissez « Peut modifier » ou « Lecture seule », puis « Autoriser ».": "On the POP page that opens, choose “Can edit” or “Read only”, then “Authorize”.",
  "Posez votre question à Popy…": "Ask Popy a question…",
  "Rien à prendre pour l’instant.": "Nothing to pick up right now.",
