  "lire vos tâches, pages et le niveau UEFN, sans rien modifier.": "read your tasks, pages and UEFN level, without changing anything.",
  "lire et modifier vos tâches et piloter UEFN par votre relais (chaque action est journalisée et annulable, une suppression attend votre validation).": "read and edit your tasks and drive UEFN through your relay (every action is logged and can be undone; deletions wait for your approval).",
