  "Vous serez renvoyé vers {0}. Vous pourrez déconnecter cette IA à tout moment dans Paramètres → IA connectées.": "You’ll be sent back to {0}. You can disconnect this AI at any time in Settings → Connected AIs.",
  "Connectez-vous pour autoriser votre IA à accéder à POP.": "Log in to let your AI access POP.",
