  "Claude, ChatGPT, Cursor, VS Code… : ajoutez un serveur MCP avec cette adresse. L’IA ouvre POP, vous cliquez sur « Autoriser », c’est connecté.": "Claude, ChatGPT, Cursor, VS Code…: add an MCP server with this address. The AI opens POP, you click “Authorize”, and you’re connected.",
