 "Note enregistrée": "Note saved",
 "Créer un compte bêta": "Create a beta account",
 "Pour donner un accès sans demande sur la liste d’attente. Vous transmettez l’identifiant et le mot de passe provisoire ; la personne choisit son mot de passe à la première connexion.": "To give access without a waitlist request. You send the username and the temporary password; the person chooses their own password the first time they log in.",
