 "Réinitialiser le mot de passe": "Reset password",
 "Donner un nouveau mot de passe provisoire à {0} ? Son mot de passe actuel ne marchera plus et il sera déconnecté.": "Give {0} a new temporary password? Their current password will stop working and they’ll be logged out.",
