 "Adresse IP": "IP address",
 "Accès protégé": "Protected access",
 "Déverrouiller pour 30 minutes": "Unlock for 30 minutes",
 "Réservé aux administrateurs de POP.": "For POP administrators only.",
 "Vous n’avez pas accès à cette page.": "You don’t have access to this page.",
 "Verrouiller": "Lock",
 "Gérer la plateforme POP : demandes d’accès à la bêta, comptes des bêta-testeurs et utilisateurs.": "Manage the POP platform: beta access requests, beta testers’ accounts and users.",
 "Vue générale": "Overview",
 "Liste d’attente{0}": "Waitlist{0}",
 "Créer un compte": "Create an account",
 "Sécurité": "Security",
 "Démarrer": "Getting started",
 "Créez votre studio et votre première map, puis invitez l’équipe dans Équipe et intégrations → Membres. Chaque invité reçoit un lien (par e-mail si l’envoi est configuré, sinon à copier).": "Create your studio and your first map, then invite the team in Team and integrations → Members. Each guest gets a link (by email if sending is configured, otherwise to copy).",
 "Rôles : propriétaire et admin gèrent tout ; membre travaille sur tout ; freelance travaille sur ses tâches ; invité lit et commente.": "Roles: owner and admin manage everything; member works on everything; freelance works on their own tasks; guest reads and comments.",
 "Tapez « / » pour insérer un bloc, « # » pour un titre, « - » pour une liste, « [] » pour une case à cocher. @Prénom mentionne un membre : il reçoit une notification.": "Type “/” to insert a block, “#” for a heading, “-” for a list, “[]” for a checkbox. @Name mentions a member: they get a notification.",
 "Historique : chaque version est horodatée et peut être restaurée. Partage : privée, équipe, ou lien public en lecture.": "History: every version is timestamped and can be restored. Sharing: private, team, or public read-only link.",
 "Post-it, formes, connecteurs, stylo, cadres. Votez avec des points, puis transformez les post-it gagnants en tâches et un cadre en page.": "Sticky notes, shapes, connectors, pen, frames. Vote with dots, then turn the winning sticky notes into tasks and a frame into a page.",
 "Planifier et Tâches": "Plan and Tasks",
 "Le générateur découpe la map en lots et tâches d’une heure, avec dépendances, jours et personnes suggérés. Une tâche ne passe « En cours » que si ses dépendances sont faites ; elle se débloque toute seule ensuite.": "The generator splits the map into batches and one-hour tasks, with suggested dependencies, days and people. A task only moves to “In progress” once its dependencies are done; it unblocks by itself after that.",
 "Le chemin critique et les alertes d’objectif s’affichent dans la chronologie.": "The critical path and goal alerts show in the timeline.",
 "UEFN : Éditeur Verse et Organiseur": "UEFN: Verse editor and Organizer",
 "Installez UEFN Link sur le PC où UEFN tourne (Paramètres → UEFN Link). Dans UEFN : Enable Project Python Scripts, puis Model Context Protocol → Start Server.": "Install UEFN Link on the PC where UEFN runs (Organizer → UEFN Link). In UEFN: Enable Project Python Scripts, then Model Context Protocol → Start Server.",
 "Éditeur Verse : Ctrl+S envoie à UEFN (écriture, compilation, erreurs à la ligne, session de test). L’assistant explique, relit et corrige sans service externe.": "Verse editor: Ctrl+S sends to UEFN (write, compile, errors on the line, test session). The assistant explains, reviews and fixes with no external service.",
 "Organiseur : recherche « tag:x type:x dossier:x option:x », multi-sélection Ctrl/Maj, Ctrl+Z annule votre dernière action. Quand UEFN est fermé, les changements attendent sa réouverture.": "Organizer: search “tag:x type:x folder:x option:x”, multi-select with Ctrl/Shift, Ctrl+Z undoes your last action. When UEFN is closed, changes wait for it to reopen.",
 "Checklist de modération, onglet Test (playtests à crédits, demandes et retours), plan heure par heure du jour J. La publication se fait dans le portail créateur d’Epic.": "Moderation checklist, Test tab (credit-based playtests, requests and feedback), hour-by-hour launch-day plan. Publishing happens in Epic’s creator portal.",
 "Règles de partage (%, fixe, par tâche), import des gains (manuel ou CSV), relevé de chacun. POP calcule, il ne fait aucun virement.": "Sharing rules (%, fixed, per task), earnings import (manual or CSV), everyone’s statement. POP calculates; it never transfers money.",
 "Intégrations": "Integrations",
 "Discord : rapport du soir automatique (webhook) et commandes /tache-suivante, /fini, /rapport (POP doit être en ligne). GitHub : issues ↔ tâches. Lore : webhook de check-in et verrous. IA connectée : jeton MCP pour Claude Code, Cursor…": "Discord: automatic evening report (webhook) and commands /tache-suivante, /fini, /rapport (POP must be online). GitHub: issues ↔ tasks. Lore: check-in webhook and locks. Connected AI: MCP token for Claude Code, Cursor…",
 "Raccourcis": "Shortcuts",
 "Ctrl K : recherche globale (tâches, pages, Verse, acteurs, membres) · Ctrl S : envoyer le Verse à UEFN · Échap : fermer.": "Ctrl K: global search (tasks, pages, Verse, actors, members) · Ctrl S: send Verse to UEFN · Ctrl Z in the Organizer: undo · Esc: close.",
 "Comment utiliser chaque partie de POP.": "How to use each part of POP.",
 "Un problème ?": "A problem?",
 "Relais UEFN : lancez": "UEFN relay: run",
 "sur le PC et gardez le résultat. Mot de passe perdu : « Mot de passe oublié » sur la page de connexion, ou demandez un lien à un admin du studio.": "on the PC and keep the output. Lost password: ask the POP team for a new temporary password.",
