 "parcours en cours": "scan in progress",
 " et mesure en priorité {0} maps populaires repérées sur fortnite.gg et dans les vidéos": " and measures first {0} popular maps spotted on fortnite.gg and in videos",
 "L’API d’Epic liste les maps de la plus récente à la plus ancienne, sans classement par joueurs. POP parcourt donc tout le catalogue petit à petit ({0}, {1} maps encore à mesurer){2}.": "Epic’s API lists maps from newest to oldest, with no player ranking. So POP scans the whole catalog bit by bit ({0}, {1} maps still to measure){2}.",
