  "chaque jour, automatiquement": "every day, automatically",
  "Précision jour après jour": "Accuracy day after day",
  "Chaque jour, l’IA apprend sur les maps les plus anciennes et se teste sur les plus récentes, qu’elle n’a jamais vues. « Percer » = dépasser {0} joueurs par jour pendant les 14 jours de test d’Epic.": "Every day, the AI learns from the oldest maps and tests itself on the most recent ones, which it has never seen. “Breaking out” = more than {0} players a day during Epic's 14-day test.",
  "Pas encore de version entraînée : il faut au moins 40 nouvelles maps sorties depuis plus de 15 jours, dont 5 qui ont percé.": "No trained version yet: at least 40 new maps released more than 15 days ago are needed, 5 of which broke out.",
