 "chemin critique": "critical path",
 "attend": "waiting for",
 "Aucune tâche pour le moment.": "No tasks yet.",
 "Une flèche va de la tâche qui débloque vers celle qui l’attend. Survolez une tâche pour voir ses liens ; cliquez pour l’ouvrir.": "An arrow goes from the task that unblocks to the one waiting for it. Hover a task to see its links; click to open it.",
 "Fonctionnalité": "Feature",
 "Retirer la dépendance": "Remove the dependency",
 "Flèche #{0} → #{1} : #{1} attend #{0}.": "Arrow #{0} → #{1}: #{1} waits for #{0}.",
 "#{0} : dépendances mises à jour": "#{0}: dependencies updated",
 "Tirer vers la tâche qui attend celle-ci": "Drag to the task that waits for this one",
 "Pour ajouter une dépendance, tirez le rond à droite d’une tâche vers la tâche qui l’attend. Cliquez une flèche pour la retirer.": "To add a dependency, drag the dot on the right of a task to the task that waits for it. Click an arrow to remove it.",
 "Connectez votre IA (Claude, Cursor, Codex…) une seule fois pour tout votre compte : elle voit vos maps perso et celles de vos studios, et choisit elle-même la map sur laquelle travailler.": "Connect your AI (Claude, Cursor, Codex…) once for your whole account: it sees your personal maps and your studios’ maps, and picks the map to work on by itself.",
 "Lecture seule : l’IA voit vos maps sans rien modifier, sur toutes les maps. Les suppressions d’acteurs attendent toujours votre validation dans Paramètres → UEFN Link.": "Read only: the AI sees your maps without changing anything, on every map. Actor deletions always wait for your approval in Settings → UEFN Link.",
 "travaille sur « {0} »": "working on “{0}”",
 "aucune map choisie": "no map chosen",
 "Redémarrez l’IA puis demandez-lui par exemple : « Travaille sur ma map POP GrassCutter ». Elle liste vos maps (list_maps) et choisit la bonne (use_map) ; vous pourrez lui faire changer de map sans la reconnecter.": "Restart the AI, then ask it for example: “Work on my POP map GrassCutter”. It lists your maps (list_maps) and picks the right one (use_map); you can have it switch maps without reconnecting it.",
 "Les IA (Claude, Cursor, Codex…) qui travaillent sur cette map : elles lisent et modifient le Verse et les acteurs UEFN comme vous, avec un journal et l’annulation.": "The AIs (Claude, Cursor, Codex…) working on this map: they read and edit the Verse and UEFN actors like you do, with a log and undo.",
 "Une IA se connecte une seule fois, pour tout votre compte. Demandez-lui ensuite de travailler sur « {0} » : elle choisit cette map elle-même.": "An AI is connected once, for your whole account. Then ask it to work on “{0}”: it picks this map by itself.",
